DROP DATABASE IF EXISTS rev12_base; DROP DATABASE IF EXISTS rev12_s3; DROP DATABASE IF EXISTS rev12_wp;
CREATE DATABASE rev12_base; CREATE DATABASE rev12_s3; CREATE DATABASE rev12_wp;
USE rev12_s3;
CREATE TABLE segreti_s3 (id INT PRIMARY KEY, nome VARCHAR(50), password VARCHAR(80)) ENGINE=InnoDB;
INSERT INTO segreti_s3 VALUES (1,'mario','PW-S3-MARIO'),(2,'luigi','PW-S3-LUIGI');
CREATE TABLE myi_s3 (id INT, nome VARCHAR(50), api_key VARCHAR(80)) ENGINE=MyISAM;
INSERT INTO myi_s3 VALUES (1,'a','APIKEY-MYI-1'),(2,'b','APIKEY-MYI-2');
CREATE TABLE dati_s3 (id INT, info VARCHAR(50)) ENGINE=MyISAM;
INSERT INTO dati_s3 VALUES (1,'DATO-DI-S3-RISERVATO');
USE rev12_wp;
CREATE TABLE wp_options (option_id BIGINT AUTO_INCREMENT PRIMARY KEY, option_name VARCHAR(191) UNIQUE, option_value LONGTEXT, autoload VARCHAR(20) DEFAULT 'yes') ENGINE=InnoDB;
INSERT INTO wp_options (option_name, option_value) VALUES ('siteurl','http://esempio.it'),('mailserver_pass','WP-MAILPASS-SEGRETO'),('auth_key','WP-AUTHKEY-SEGRETO'),('blogname','Il mio blog'),('rdacademy_chiave_api','CHIAVE-API-IN-OPTIONS'),('stripe_sk','sk_live_STRIPESEGRETO'),('admin_email','a@b.it');
CREATE TABLE wp_users (ID BIGINT AUTO_INCREMENT PRIMARY KEY, user_login VARCHAR(60), user_pass VARCHAR(255), user_email VARCHAR(100), user_activation_key VARCHAR(255), display_name VARCHAR(250)) ENGINE=InnoDB;
INSERT INTO wp_users VALUES (1,'admin','$P$BHASHADMIN000','a@b.it','ACTKEY1','Admin'),(2,'ed','$P$BHASHED00000','e@b.it','','Ed');
CREATE TABLE wp_usermeta (umeta_id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT, meta_key VARCHAR(255), meta_value LONGTEXT) ENGINE=InnoDB;
INSERT INTO wp_usermeta (user_id, meta_key, meta_value) VALUES (1,'session_tokens','SESS-TOK-SEGRETO'),(1,'nickname','admin');
CREATE TABLE wp_woocommerce_api_keys (key_id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT, description VARCHAR(200), permissions VARCHAR(10), consumer_key CHAR(64), consumer_secret CHAR(43), truncated_key CHAR(7)) ENGINE=InnoDB;
INSERT INTO wp_woocommerce_api_keys VALUES (1,1,'chiave negozio','read_write','HMACCONSUMERKEYHASH0123456789abcdef0123456789abcdef0123456789ab','cs_SEGRETO','abc1234');
CREATE TABLE rdacademy_wpx (id INT AUTO_INCREMENT PRIMARY KEY, a VARCHAR(50)) ENGINE=InnoDB;
INSERT INTO rdacademy_wpx (a) VALUES ('uno');
USE rev12_base;
CREATE TABLE utenti (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(50), user_pass VARCHAR(80), token VARCHAR(80), KEY idx_token (token)) ENGINE=InnoDB;
INSERT INTO utenti (nome,user_pass,token) VALUES ('zeta','HASH-ZETA','tok-aaa'),('alfa','HASH-ALFA','tok-zzz'),('emme','HASH-EMME','tok-mmm');
CREATE TABLE rdacademy_impostazioni (id INT AUTO_INCREMENT PRIMARY KEY, chiave VARCHAR(100) UNIQUE, valore TEXT) ENGINE=InnoDB;
INSERT INTO rdacademy_impostazioni (chiave, valore) VALUES ('smtp_password','SMTP-PW-SEGRETA'),('nome_sito','Accademia'),('chiave_api_claude','sk-ant-CHIAVE-CLAUDE-SEGRETA'),('parola_d_ordine_ftp','FTP-PAROLA-SEGRETA'),('tema','scuro');
CREATE TABLE chiavi (id INT AUTO_INCREMENT PRIMARY KEY, servizio VARCHAR(50), chiave_api VARCHAR(80), private_key TEXT, pin VARCHAR(10), credenziali VARCHAR(80)) ENGINE=InnoDB;
INSERT INTO chiavi (servizio, chiave_api, private_key, pin, credenziali) VALUES ('claude','sk-ant-COLONNA-CHIAVE-API','-----BEGIN PRIVATE KEY-----XYZ','4829','user:PWCRED');
CREATE TABLE innocua (id INT AUTO_INCREMENT PRIMARY KEY, a INT, b VARCHAR(50)) ENGINE=InnoDB;
INSERT INTO innocua (a,b) VALUES (1,'x'),(2,'y'),(3,'z');
CREATE TABLE myi (id INT, b VARCHAR(50)) ENGINE=MyISAM; INSERT INTO myi VALUES (1,'m');
CREATE TABLE ari (id INT, b VARCHAR(50)) ENGINE=Aria; INSERT INTO ari VALUES (1,'a');
CREATE VIEW vista_s3 AS SELECT id, info FROM rev12_s3.dati_s3;
CREATE TABLE mrg_s3 (id INT, info VARCHAR(50)) ENGINE=MRG_MyISAM UNION=(rev12_s3.dati_s3) INSERT_METHOD=LAST;
CREATE TABLE mrg_s3k (id INT, nome VARCHAR(50), api_key VARCHAR(80)) ENGINE=MRG_MyISAM UNION=(rev12_s3.myi_s3);
CREATE TABLE padre (id INT PRIMARY KEY, n VARCHAR(20)) ENGINE=InnoDB; INSERT INTO padre VALUES (1,'p1'),(2,'p2');
CREATE TABLE sessioni (id INT PRIMARY KEY, token VARCHAR(40), KEY(token)) ENGINE=InnoDB; INSERT INTO sessioni VALUES (1,'TOKEN-SESSIONE-ABC'),(2,'TOKEN-SESSIONE-XYZ');
CREATE TABLE accessi (id INT AUTO_INCREMENT PRIMARY KEY, rif_sessione VARCHAR(40), FOREIGN KEY (rif_sessione) REFERENCES sessioni(token)) ENGINE=InnoDB;
CREATE TABLE part_tok (id INT, nome VARCHAR(20), token VARCHAR(40)) ENGINE=InnoDB PARTITION BY RANGE COLUMNS(token) (PARTITION p_am VALUES LESS THAN ('n'), PARTITION p_nz VALUES LESS THAN (MAXVALUE));
INSERT INTO part_tok VALUES (1,'uno','abc-segreto'),(2,'due','xyz-segreto');
CREATE TABLE big (id INT AUTO_INCREMENT PRIMARY KEY, x INT, p CHAR(200) DEFAULT 'pppp') ENGINE=InnoDB;
INSERT INTO big (x) SELECT seq FROM seq_1_to_2000000;
USE rev12_wp;
CREATE TABLE figlio_fk (id INT AUTO_INCREMENT PRIMARY KEY, padre_id INT, FOREIGN KEY (padre_id) REFERENCES rev12_base.padre(id) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB;
INSERT INTO figlio_fk (padre_id) VALUES (1),(1),(2);
